<?php
use EIPSI\StudyEngine\Longitudinal as L;use EIPSI\StudyEngine\Persistence as P;
function s2_wait($file,$result=null){$end=microtime(true)+25;while(!is_file($file)){if($result!==null&&is_file($result))throw new RuntimeException('Worker exited before barrier: '.substr(file_get_contents($result),0,300));if(microtime(true)>$end)throw new RuntimeException('SEC2 race timeout: '.basename($file));usleep(10000);}}
function s2_race(array $left,array $right,bool $blocked=true): array {
 $dir='/tmp/eipsi-sec2-race-'.bin2hex(random_bytes(8));mkdir($dir,0700);$processes=array();$start=microtime(true);
 try{
  foreach(array($left,$right)as$i=>$in){$in['clock']=$GLOBALS['pf_now'];$in['request']=bin2hex(random_bytes(6));file_put_contents($dir.'/input'.$i.'.json',json_encode($in));$pipes=array();$processes[$i]=proc_open(array(PHP_BINARY,__DIR__.'/race-worker.php',$dir,(string)$i),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout'.$i,'w'),2=>array('file',$dir.'/stderr'.$i,'w')),$pipes);pe_assert(is_resource($processes[$i]),'Spawn');fclose($pipes[0]);}
  s2_wait($dir.'/ready0');s2_wait($dir.'/ready1');touch($dir.'/start0');s2_wait($dir.'/locked0',$dir.'/result0.json');touch($dir.'/start1');s2_wait($dir.'/attempt1');usleep(100000);if($blocked)pe_assert(!is_file($dir.'/result1.json'),'Operation escaped the authoritative lock');touch($dir.'/release0');$out=array();
  foreach(array(0,1)as$i){s2_wait($dir.'/result'.$i.'.json');pe_assert(proc_close($processes[$i])===0,'Worker failed');unset($processes[$i]);$out[]=json_decode(file_get_contents($dir.'/result'.$i.'.json'),true);}
  echo 'SEC2 race '.json_encode(array('left'=>$left['mode'],'right'=>$right['mode'],'seconds'=>round(microtime(true)-$start,3)))."\n";return$out;
 }finally{touch($dir.'/release0');touch($dir.'/release1');foreach($processes as$p){proc_terminate($p);proc_close($p);}foreach(glob($dir.'/*')as$f)unlink($f);rmdir($dir);}
}
function s2_input($p,$f,$mode,$native=null,$point=null){$id=$f['view']['next_action']['payload']['assessment_execution_id']??null;if($id===null)foreach($f['view']['snapshot']['instances']as$i)if($i['definition_id']==='E_ASSESSMENT'){$id=$i['id'];break;}$node=null;foreach($p['definition']['nodes']as$n)if($n['id']===$f['view']['snapshot']['instances'][$id]['definition_id'])$node=$n;return array('mode'=>$mode,'point'=>$point,'public'=>$p['public'],'version'=>$p['version'],'token'=>$f['token'],'native'=>$native,'native_version'=>$node['metadata']['native_version_id'],'binding'=>array('kind'=>'STUDY_SESSION','public_id'=>$p['public'],'execution_id'=>$f['access']['execution_id'],'study_version_id'=>$p['version'],'participant_id'=>$f['access']['participant_id'],'block_execution_id'=>$id));}
function s2_native_count($f){return(int)pf_db()->row(pf_db()->prepare('SELECT COUNT(*) AS n FROM '.pf_db()->table('native_executions').' WHERE management_execution=%s',$f['access']['execution_id']))['n'];}
$cases['Race open commits before Pause and remains recoverable']=function(){$p=s2_publish();$f=pf_enroll($p);$r=s2_race(s2_input($p,$f,'open',null,'native_assignment_created'),s2_input($p,$f,'pause'));pe_assert(isset($r[0]['execution_id'])&&($r[1]['state']??null)==='PAUSED','Bad open/pause outcome '.json_encode($r));$_COOKIE[L\Identity::cookieName($p['public'])]=$f['token'];pe_assert(s2_owner()->view($r[0]['execution_id'])['state']==='ACTIVE'&&s2_native_count($f)===1,'Open work lost');};
$cases['Race Pause commits first and no new Native attempt is persisted']=function(){$p=s2_publish();$f=pf_enroll($p);$r=s2_race(s2_input($p,$f,'pause',null,'before_study_state_commit'),s2_input($p,$f,'open'));pe_assert(($r[0]['state']??null)==='PAUSED'&&($r[1]['error']??null)==='STUDY_PAUSED'&&s2_native_count($f)===0,'Partial admission '.json_encode($r));};
$cases['Race existing submit wins before Pause without losing science']=function(){$p=s2_publish();$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];pf_native_fixture_command(s2_owner(),$id,'open');s2_domain($f);$r=s2_race(s2_input($p,$f,'submit',$id,'before_native_command_commit'),s2_input($p,$f,'pause'));pe_assert(($r[0]['state']??null)==='COMPLETED'&&($r[1]['state']??null)==='PAUSED','Submit race '.json_encode($r));pe_assert(count((new P\SubmissionJournalRepository(pf_db()))->list($f['access']['execution_id']))===1,'Missing final response');};
$cases['Race Pause wins and existing submit still commits normally']=function(){$p=s2_publish();$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];pf_native_fixture_command(s2_owner(),$id,'open');s2_domain($f);$r=s2_race(s2_input($p,$f,'pause',null,'before_study_state_commit'),s2_input($p,$f,'submit',$id));pe_assert(($r[1]['state']??null)==='COMPLETED','Pause rejected submit '.json_encode($r));pe_assert(count((new P\SubmissionJournalRepository(pf_db()))->list($f['access']['execution_id']))===1,'Missing journal');};
$cases['Race recovery and Pause preserve the same session checkpoint']=function(){$p=s2_publish();$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];$open=pf_native_fixture_command(s2_owner(),$id,'open');$key=$open['definition']['elements'][0]['response_key'];$partial=pf_native_fixture_command(s2_owner(),$id,'partial',array($key=>'Respuesta para recuperar'));$r=s2_race(s2_input($p,$f,'recover',$id,'before_native_recovery_commit'),s2_input($p,$f,'pause'));pe_equal($r[0]['session']??null,$partial['session'],'Recovery race changed partial');pe_assert(($r[1]['state']??null)==='PAUSED'&&s2_native_count($f)===1,'Recovery duplicated');};
$cases['Race Pause then recovery still restores the original attempt']=function(){$p=s2_publish();$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];$open=pf_native_fixture_command(s2_owner(),$id,'open');$r=s2_race(s2_input($p,$f,'pause',null,'before_study_state_commit'),s2_input($p,$f,'recover',$id));pe_assert(($r[1]['execution_id']??null)===$id&&s2_native_count($f)===1,'Recovery blocked or replaced '.json_encode($r));};
$cases['Race Resume and scheduler never activate before Resume commit']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish(true);$f=pf_enroll($p);s2_state($p,'PAUSED');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+10800));$r=s2_race(s2_input($p,$f,'resume',null,'before_study_state_commit'),s2_input($p,$f,'advance'),false);pe_assert(($r[0]['state']??null)==='ACTIVE'&&isset($r[1]['advanced']),'Scheduler ran before commit '.json_encode($r));$w=new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock());$w->advanceBatch(100);$one=pf_owner()->view($f['access']['execution_id']);$w->advanceBatch(100);pe_equal($one['snapshot'],pf_owner()->view($f['access']['execution_id'])['snapshot'],'Duplicate resumption');pe_assert($one['next_action']['kind']==='OPEN_ASSESSMENT','Resume failed');}finally{s2_time($saved);}};
